/* @lc app=leetcode id=2569 lang=kotlin */
class Solution { fun handleQuery(nums1: IntArray, nums2: IntArray, queries: Array<IntArray>): LongArray = IntArray(4 * nums1.size).let { tree -> BooleanArray(4 * nums1.size).let { lazy -> val push = { node: Int, l: Int, r: Int -> if (lazy[node]) ((l + r) / 2).let { mid -> tree.set(2 * node, (mid - l + 1) - tree[2 * node]).also { lazy[2 * node] = !lazy[2 * node] }.also { tree[2 * node + 1] = (r - mid) - tree[2 * node + 1] }.also { lazy[2 * node + 1] = !lazy[2 * node + 1] }.also { lazy[node] = false } } else Unit } val build = DeepRecursiveFunction<Triple<Int, Int, Int>, Unit> { (node, l, r) -> if (l == r) tree[node] = nums1[l] else ((l + r) / 2).let { mid -> callRecursive(Triple(2 * node, l, mid)).also { callRecursive(Triple(2 * node + 1, mid + 1, r)) }.also { tree[node] = tree[2 * node] + tree[2 * node + 1] } } } val update = DeepRecursiveFunction<IntArray, Unit> { args -> args[0].let { node -> args[1].let { l -> args[2].let { r -> args[3].let { ql -> args[4].let { qr -> if (ql <= l && r <= qr) tree.set(node, (r - l + 1) - tree[node]).also { lazy[node] = !lazy[node] } else push(node, l, r).let { ((l + r) / 2).let { mid -> (if (ql <= mid) callRecursive(intArrayOf(2 * node, l, mid, ql, qr)) else Unit).also { if (qr > mid) callRecursive(intArrayOf(2 * node + 1, mid + 1, r, ql, qr)) }.also { tree[node] = tree[2 * node] + tree[2 * node + 1] } } } } } } } } build.callRecursive(Triple(1, 0, nums1.size - 1)).let { queries.fold(Triple(nums2.fold(0L) { acc, x -> acc + x.toLong() }, LongArray(queries.count { it[0] == 3 }), 0)) { (s2, arr, idx), q -> if (q[0] == 1) update.callRecursive(intArrayOf(1, 0, nums1.size - 1, q[1], q[2])).let { Triple(s2, arr, idx) } else if (q[0] == 2) Triple(s2 + q[1].toLong() * tree[1], arr, idx) else arr.set(idx, s2).let { Triple(s2, arr, idx + 1) } }.second } } } }